#include <iostream>
using namespace std;
int main() {
    int n, m;
    int h[105][105];

    cin >> n >> m;
    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++)
            cin >> h[i][j];
    for(int i = 0; i <= max(n, m) + 1; i++)
        h[i][0] = h[0][i] = h[i][m + 1] = h[n + 1][i] = 1e9;

    int ans = 0;
    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++) {
            bool ok = true;
            for(int i2 = i - 1; i2 <= i + 1; i2++)
                for(int j2 = j - 1; j2 <= j + 1; j2++)
                    if(h[i][j] > h[i2][j2]) {
                        ok = false;
                        break;
                    }
            ans += ok;
        }
    cout << ans;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
struct Combo {
    int sum, mx, mn, id;
};
bool cmp(const Combo &a, const Combo &b) {
    if (a.sum != b.sum) return a.sum < b.sum;
    if (a.mx != b.mx) return a.mx < b.mx;
    if (a.mn != b.mn) return a.mn < b.mn;
    return a.id < b.id;
}
int main() {
    int n, k;
    cin >> n >> k;
    vector<Combo> v(n);
    for (int i = 0; i < n; i++) {
        v[i].sum = 0;
        v[i].mx = -1;
        v[i].mn = 1e9;
        v[i].id = i + 1;
        for (int j = 0; j < k; j++) {
            int x;
            cin >> x;
            v[i].sum += x;
            v[i].mx = max(v[i].mx, x);
            v[i].mn = min(v[i].mn, x);
        }
    }
    sort(v.begin(), v.end(), cmp);
    for (int i = 0; i < n; i++) {
        cout << v[i].id;
        if (i + 1 < n) cout << " ";
    }
    cout << endl;
    return 0;
}
